import { OptionalProps } from '@mikro-orm/core'
import { Entity, Enum, OneToOne, PrimaryKey, Property } from '@mikro-orm/decorators/legacy'

import { SVT_DB_ENUM_VALUES } from '../enums'

import { SvtDbWaferTypeMapEntity } from './svt-db-wafer-type-map.entity'


/**
 * `main."WaferType"`: a wafer design (engineering run) with its foundry and technology.
 * `id` is `integer GENERATED BY DEFAULT AS IDENTITY` in the database, hence `generated`; the unique
 * constraints get PostgreSQL's default names through `SvtDbNamingStrategy`. Scalar properties declare
 * their `type` explicitly: Vitest (esbuild) emits no decorator metadata, the bundle and the CLI do.
 */
@Entity({ tableName: 'WaferType' })
export class SvtDbWaferTypeEntity {

    @PrimaryKey({ type: 'integer', autoincrement: true, generated: 'by default as identity' })
    id!: number

    @Property({ type: 'string', length: 50, unique: true })
    name!: string

    @Enum({ nativeEnumName: 'engineeringRun', items: SVT_DB_ENUM_VALUES.engineeringRun, unique: true })
    engineeringRun!: string

    @Enum({ nativeEnumName: 'foundryName', items: SVT_DB_ENUM_VALUES.foundryName })
    foundry!: string

    @Enum({ nativeEnumName: 'waferTech', items: SVT_DB_ENUM_VALUES.waferTech })
    technology!: string

    /** The wafer map, when one has been uploaded (`WaferTypeMap` shares this entity's id). */
    @OneToOne({ entity: () => SvtDbWaferTypeMapEntity, mappedBy: 'waferType', nullable: true })
    map?: SvtDbWaferTypeMapEntity;

    [OptionalProps]?: 'id' | 'map'

}
